def block_masks(grid, sep):
    """For each segment between sep-columns, its cells as a binary mask over the segment's rows x width."""
    h = len(grid)
    out = {}
    for c, o in segments(grid, sep):
        wd = 0
        while o + wd < len(grid[0]) and grid[0][o + wd] != sep:
            wd += 1
        out[c] = [[1 if grid[i][o + j] == c else 0 for j in range(wd)] for i in range(h)]
